using SixLabors.ImageSharp.Formats.Av1.Bitstream;
using SixLabors.ImageSharp.Formats.Av1.Obu;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// End-to-end intra decode of a real 128x128 all-intra clip that mixes DC and SMOOTH prediction across
/// its 64x64 blocks. The reconstruction is compared against dav1d 1.4.1 with the loop-filter, CDEF and
/// loop-restoration post-filters disabled (this decoder does not apply them yet); the pre-filter luma
/// matches dav1d bit-exactly, confirming the non-directional intra prediction is correct.
/// </summary>
public class Av1SmoothModeDecodeTests
{
    private static readonly byte[] SequencePayload = Convert.FromHexString("1819bfffec02");

    private static readonly byte[] FramePayload = Convert.FromHexString(
        "1780041000048c0000e2462ad9b42655895c4775463e2cfc148b923ad111cce78d7a0795b1c5e3c1564f450436048573cb0af86e8d1365ff68a2cb015eb68049b32ff6ded56537414eb83a6e7ecddb111fd8e0edd37a3c2d9280");

    [Fact]
    public void DecodeTile_SmoothAndDcBlocks_MatchesDav1dPreFilter()
    {
        ObuSequenceHeader sequenceHeader = ObuSequenceHeader.Parse(SequencePayload);
        Av1BitStreamReader reader = new(FramePayload);
        ObuFrameHeader frameHeader = ObuFrameHeader.ParseIntra(ref reader, sequenceHeader);

        int tileGroupStart = (frameHeader.EndBitPosition + 7) >> 3;
        ObuTileGroup tileGroup = ObuTileGroup.Parse(FramePayload.AsSpan(tileGroupStart), frameHeader);
        (int offset, int length) = tileGroup.GetTile(0);

        Av1IntraTileDecoder decoder = new(sequenceHeader, frameHeader);
        decoder.DecodeTile(FramePayload.AsMemory(tileGroupStart + offset, length));

        Assert.All(decoder.ChromaU.Samples, s => Assert.Equal(128, s));
        Assert.All(decoder.ChromaV.Samples, s => Assert.Equal(128, s));

        byte[] reference = Convert.FromBase64String(Dav1dPreFilterLumaBase64);
        Assert.True(decoder.Luma.Samples.AsSpan().SequenceEqual(reference), "Reconstructed luma differs from the dav1d pre-filter reference.");
    }

    private const string Dav1dPreFilterLumaBase64 =
        "";
}
